const log = [];
const task = (name, ms, cb) => { log.push("start " + name); setTimeout(() => { log.push("end " + name); cb(null, name); }, ms); };
function series(items, done) {
  const out = [];
  (function next(i) {
    if (i === items.length) return done(out);
    task(items[i][0], items[i][1], (e, r) => { out.push(r); next(i + 1); });
  })(0);
}
series([["a", 10], ["b", 30], ["c", 40]], (out) => console.log(log.join(", ")));

