import { setTimeout as sleep } from "node:timers/promises";
await Promise.all([
  sleep(20).then(() => "B"),
  sleep(5).then(() => { throw new Error("D failed"); }),
  sleep(10).then(() => "A"),
]).then((r) => r.join(","), (e) => (e.errors ? "all failed" : e.message)).then(console.log);

