import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
const out = [];
await pipeline(
  Readable.from(["data","streams","flow"]),
  async function* (src) { for await (const c of src) { yield c.toUpperCase(); } },
  async function* (src) { for await (const c of src) { yield c; } },
  async function (src) { for await (const c of src) out.push(c); },
);
console.log(out.join(" "));

